content:
{
  "promos": [
    {
      "title": "The Church Calls Her a Lie",
      "start_block": "B014",
      "end_block": "B046",
      "hook": "The High Priest's cold, accusatory voice cuts in: \"You married this woman as a nameless beggar...\" over Alexander and Juliana standing defiant at the altar.",
      "cliffhanger": "Juliana shouts, \"God married us, Father! You are just angry no one asked you first!\" — the camera holds on her furious face as the priest's authority is openly defied, with no resolution to the marriage's validity.",
      "why": "A public humiliation of the couple by a powerful priest escalates into a defiant, emotional outburst that leaves the marriage's fate hanging.",
      "context_gap": "A stranger may not know why Alexander was a nameless beggar or why the marriage was a hedge ceremony."
    },
    {
      "title": "Ten Days to Lose Her Twice",
      "start_block": "B055",
      "end_block": "B071",
      "hook": "The High Priest booms, \"And I have the power to undo in one hearing what took you three years to steal!\" while waving the letter before the congregation.",
      "cliffhanger": "The High Priest warns ominously, \"Ten days, Duke. Choose your witnesses well,\" leaving the trial's outcome and the couple's future completely unresolved.",
      "why": "A direct threat to destroy the marriage sets a ticking clock, and the cut lands right before the trial that could tear them apart.",
      "context_gap": "A stranger may not know the full history of the stolen title or why the High Priest has such authority."
    },
    {
      "title": "Catherine's Ten Days of Plenty",
      "start_block": "B047",
      "end_block": "B075",
      "hook": "Catherine leans against a stone archway and taunts, \"Careful, healer. The floor isn't finished with you,\" while Juliana is still reeling from the priest's attack.",
      "cliffhanger": "Catherine watches the priest depart and whispers maliciously, \"Ten days is plenty of time,\" signaling a new scheme is about to unfold.",
      "why": "The villain's quiet threat after the public confrontation promises future betrayal and ends on an ominous, unresolved note.",
      "context_gap": "A stranger may not know Catherine's history with Alexander or why she hates Juliana."
    }
  ],
  "moments": [
    {
      "start_block": "B008",
      "end_block": "B012",
      "kind": "hook",
      "description": "The High Priest declares the sanctuary under Crown seizure and orders no one to leave, establishing immediate danger for Alexander and Juliana."
    },
    {
      "start_block": "B022",
      "end_block": "B024",
      "kind": "emotional",
      "description": "Alexander firmly states, \"She married the man... not the title,\" as the High Priest derisively dismisses their marriage as that of a vagrant and a ruined lady."
    },
    {
      "start_block": "B034",
      "end_block": "B036",
      "kind": "emotional",
      "description": "Juliana tearfully but fiercely declares, \"I didn't ask this church for permission to survive... I won't ask it for permission to love.\""
    },
    {
      "start_block": "B064",
      "end_block": "B065",
      "kind": "cliffhanger",
      "description": "The High Priest chillingly warns Alexander that if the council rules against him, the county will watch him lose Juliana twice, and Alexander accepts the wager."
    }
  ]
}
